package com.folio.reader;

import android.app.Activity;
import android.content.Intent;
import android.database.sqlite.SQLiteDatabase;
import android.database.Cursor;
import android.content.ContentValues;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.util.Base64;
import androidx.activity.result.ActivityResult;
import com.getcapacitor.*;
import com.getcapacitor.annotation.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;
import org.libtorrent4j.*;
import com.github.junrar.Archive;
import com.github.junrar.rarfile.FileHeader;

@CapacitorPlugin(name="FolioNative",permissions={@Permission(alias="notifications",strings={"android.permission.POST_NOTIFICATIONS"})})
public class FolioNative extends Plugin {
 private SQLiteDatabase db; private File booksDir,downloadDir; private final ExecutorService pool=Executors.newCachedThreadPool();
 private final ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor(); private final Map<String,TorrentHandle> handles=new ConcurrentHashMap<>(); private SessionManager session;
 private JSONArray jobs=new JSONArray();
 @Override public void load(){try{db=getContext().openOrCreateDatabase("folio.sqlite",0,null);db.execSQL("CREATE TABLE IF NOT EXISTS state (key TEXT PRIMARY KEY,value TEXT NOT NULL)");booksDir=new File(getContext().getFilesDir(),"books");downloadDir=new File(getContext().getFilesDir(),"downloads");booksDir.mkdirs();downloadDir.mkdirs();jobs=new JSONArray(read("jobs","[]"));for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);if(!j.optString("status").equals("Complete")&&!j.optString("status").equals("Cancelled"))j.put("status","Paused");}timer.scheduleAtFixedRate(this::tick,1,1,TimeUnit.SECONDS);}catch(Exception e){android.util.Log.e("Folio","Startup",e);}}
 private synchronized String read(String key,String fallback){try(Cursor c=db.rawQuery("SELECT value FROM state WHERE key=?",new String[]{key})){return c.moveToFirst()?c.getString(0):fallback;}}
 private synchronized Object write(String key,Object value){ContentValues v=new ContentValues();v.put("key",key);v.put("value",value.toString());db.insertWithOnConflict("state",null,v,SQLiteDatabase.CONFLICT_REPLACE);return value;}
 private JSONArray books() throws Exception{return new JSONArray(read("books","[]"));}
 private JSONObject book(String id) throws Exception{JSONArray a=books();for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id))return a.getJSONObject(i);throw new Exception("Book not found");}
 private synchronized JSONObject job(String id) throws Exception{for(int i=0;i<jobs.length();i++)if(jobs.getJSONObject(i).getString("id").equals(id))return jobs.getJSONObject(i);throw new Exception("Download not found");}
 private void reply(PluginCall call,Object value){JSObject r=new JSObject();r.put("result",value==null?JSONObject.NULL:value);call.resolve(r);}
 private boolean supported(String name){return name.toLowerCase().matches(".*\\.(epub|pdf|cbz|cbr)$");}
 private File safeFile(File dir,String name) throws Exception{File f=new File(dir,name);if(!f.getCanonicalPath().startsWith(dir.getCanonicalPath()+File.separator))throw new Exception("Unsafe file path");return f;}
 private byte[] bytes(InputStream in,long max) throws Exception{try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];long size=0;int n;while((n=stream.read(b))!=-1){size+=n;if(size>max)throw new Exception("File exceeds the supported size");out.write(b,0,n);}return out.toByteArray();}}
 private byte[] network(String url,long max) throws Exception{URL u=new URL(url);if(!u.getProtocol().equals("https"))throw new Exception("Use HTTPS downloads");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);try{return bytes(c.getInputStream(),max);}finally{c.disconnect();}}
 private synchronized JSONObject store(File file,JSONObject meta) throws Exception{if(!supported(file.getName()))throw new Exception("Choose an EPUB, PDF, CBZ or CBR book");MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)md.update(b,0,n);}StringBuilder hash=new StringBuilder();for(byte b:md.digest())hash.append(String.format("%02x",b));String id=hash.toString();JSONArray all=books();for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("id").equals(id))return all.getJSONObject(i);String ext=file.getName().substring(file.getName().lastIndexOf('.')).toLowerCase();File dest=new File(booksDir,id+ext);Files.copy(file.toPath(),dest.toPath(),StandardCopyOption.REPLACE_EXISTING);JSONObject b=new JSONObject(meta.toString());b.put("id",id);b.put("file",dest.getAbsolutePath());b.put("format",ext.substring(1).toUpperCase());b.put("title",meta.optString("title",file.getName().replaceFirst("\\.[^.]+$","")));b.put("author",meta.optString("author","Your collection"));b.put("added",System.currentTimeMillis());b.put("progress",0);JSONArray next=new JSONArray();next.put(b);for(int i=0;i<all.length();i++)next.put(all.get(i));write("books",next);return b;}
 @PluginMethod public void execute(PluginCall call){String method=call.getString("method","");if((method.equals("download")||method.equals("torrent"))&&android.os.Build.VERSION.SDK_INT>=33&&getPermissionState("notifications")!=PermissionState.GRANTED&&!call.getData().optBoolean("notificationAsked")){call.getData().put("notificationAsked",true);requestPermissionForAlias("notifications",call,"notificationPermission");return;}if(method.equals("import")||method.equals("torrentFile")){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,method.equals("import"));startActivityForResult(call,intent,"picked");return;}pool.execute(()->{try{JSONObject a=call.getObject("args",new JSObject());Object value=null;switch(method){
 case "background":getActivity().runOnUiThread(()->getActivity().moveTaskToBack(true));value=true;break;
 case "state":value=new JSONObject().put("books",books()).put("addons",new JSONArray(read("addons","[]"))).put("settings",new JSONObject(read("settings","{}"))).put("jobs",new JSONArray(jobs.toString()));break;
 case "jobs":value=new JSONArray(jobs.toString());break;
 case "settings":value=write("settings",a);break;
 case "addons":{JSONArray array=call.getData().getJSONArray("args");value=write("addons",array);break;}
 case "bytes":{File f=new File(book(a.getString("id")).getString("file"));value=Base64.encodeToString(bytes(new FileInputStream(f),128L*1024*1024),Base64.NO_WRAP);break;}
 case "read":value=comic(new File(book(a.getString("id")).getString("file")));break;
 case "progress":{JSONArray all=books();for(int i=0;i<all.length();i++){JSONObject b=all.getJSONObject(i);if(b.getString("id").equals(a.getString("id"))){b.put("location",a.opt("location"));b.put("progress",a.optDouble("progress",0));b.put("bookmarks",a.optJSONArray("bookmarks"));b.put("lastRead",System.currentTimeMillis());}}value=write("books",all);break;}
 case "remove":{JSONArray all=books(),next=new JSONArray();for(int i=0;i<all.length();i++){JSONObject b=all.getJSONObject(i);if(!b.getString("id").equals(a.getString("id")))next.put(b);else if(a.optBoolean("deleteFile"))new File(b.getString("file")).delete();}value=write("books",next);break;}
 case "download":value=download(a.getJSONObject("source"),a.getJSONObject("book"));break;
 case "torrent":value=addTorrent(a.getString("input"));break;
 case "select":{JSONObject j=job(a.getString("id"));TorrentHandle h=handles.get(j.getString("id"));if(h==null)throw new Exception("Resume the torrent first");TorrentInfo ti=h.torrentFile();Priority[] priorities=Priority.array(Priority.IGNORE,ti.numFiles());int index=-1;for(int i=0;i<ti.numFiles();i++)if(ti.files().filePath(i).equals(a.getString("file"))&&supported(a.getString("file"))){safeFile(downloadDir,a.getString("file"));index=i;}if(index<0)throw new Exception("Select a supported book");priorities[index]=Priority.DEFAULT;h.prioritizeFiles(priorities);h.resume();j.put("selected",a.getString("file"));j.put("index",index);j.put("status","Downloading");value=j;break;}
 case "job":{JSONObject j=job(a.getString("id"));String action=a.getString("action");if(j.optString("kind").equals("http"))throw new Exception("HTTP downloads finish automatically; retry failures from Discover");TorrentHandle h=handles.get(j.getString("id"));if(action.equals("resume")){if(h==null){TorrentInfo ti=new TorrentInfo(new File(downloadDir,j.getString("id")+".torrent"));h=startTorrent(ti);handles.put(j.getString("id"),h);if(j.has("index")){Priority[] p=Priority.array(Priority.IGNORE,ti.numFiles());p[j.getInt("index")]=Priority.DEFAULT;h.prioritizeFiles(p);}}h.resume();j.put("status",j.has("selected")?"Downloading":"Choose file");}else{if(h!=null)h.pause();j.put("status",action.equals("cancel")?"Cancelled":"Paused");}value=true;break;}
 case "importJob":{JSONObject j=job(a.getString("id"));if(j.optDouble("progress")<1)throw new Exception("Download is not complete");value=store(safeFile(downloadDir,j.getString("selected")),new JSONObject());break;}
 default:throw new Exception("Unknown operation");}reply(call,value);}catch(Throwable e){call.reject(e.getMessage()==null?e.toString():e.getMessage());}});}
 @PermissionCallback private void notificationPermission(PluginCall call){execute(call);}
 @ActivityCallback private void picked(PluginCall call,ActivityResult result){if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK){reply(call,new JSONArray());return;}pool.execute(()->{try{Intent intent=result.getData();List<Uri> uris=new ArrayList<>();if(intent.getClipData()!=null)for(int i=0;i<intent.getClipData().getItemCount();i++)uris.add(intent.getClipData().getItemAt(i).getUri());else if(intent.getData()!=null)uris.add(intent.getData());JSONArray out=new JSONArray();for(Uri uri:uris){String name="book.epub";try(Cursor c=getContext().getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(c.getColumnIndexOrThrow(OpenableColumns.DISPLAY_NAME));}File tmp=new File(getContext().getCacheDir(),new File(name).getName());try(InputStream in=getContext().getContentResolver().openInputStream(uri);OutputStream os=new FileOutputStream(tmp)){byte[] buffer=new byte[65536];int n;long total=0;while((n=in.read(buffer))!=-1){total+=n;if(total>512L*1024*1024)throw new Exception("File exceeds 512 MB");os.write(buffer,0,n);}}if(call.getString("method").equals("torrentFile")){reply(call,addTorrent(tmp.getAbsolutePath()));return;}out.put(store(tmp,new JSONObject()));tmp.delete();}reply(call,out);}catch(Throwable e){call.reject(e.getMessage());}});}
 private void foreground(){getActivity().runOnUiThread(()->{try{getContext().startForegroundService(new Intent(getContext(),DownloadService.class));}catch(Exception e){android.util.Log.w("Folio","Foreground",e);}});}
 private JSONObject download(JSONObject source,JSONObject meta) throws Exception{String format=source.getString("format").toLowerCase();if(!supported("b."+format))throw new Exception("Unsupported format");String name=UUID.randomUUID()+"."+format;JSONObject j=new JSONObject().put("id",name).put("selected",name).put("status","Downloading").put("progress",0).put("kind","http");synchronized(this){jobs.put(j);}foreground();try{URL u=new URL(source.getString("url"));if(!u.getProtocol().equals("https"))throw new Exception("Use HTTPS downloads");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);File file=new File(downloadDir,name);try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(file)){long size=c.getContentLengthLong(),received=0;int n;byte[] buffer=new byte[65536];while((n=in.read(buffer))!=-1){received+=n;if(received>512L*1024*1024)throw new Exception("Download exceeds 512 MB");out.write(buffer,0,n);j.put("progress",size>0?(double)received/size:0);}}finally{c.disconnect();}j.put("status","Complete");j.put("progress",1);return store(file,meta);}catch(Exception e){j.put("status","Error");throw e;}}
 private synchronized SessionManager engine(){if(session==null){session=new SessionManager();session.start();}return session;}
 private TorrentHandle startTorrent(TorrentInfo ti) throws Exception{Priority[] priorities=Priority.array(Priority.IGNORE,ti.numFiles());engine().download(ti,downloadDir,null,priorities,null,null);for(int i=0;i<100;i++){TorrentHandle h=engine().find(ti.infoHash());if(h!=null&&h.isValid())return h;Thread.sleep(100);}throw new Exception("Could not start torrent");}
 private JSONObject addTorrent(String input) throws Exception{foreground();byte[] data;if(input.startsWith("magnet:?")){data=engine().fetchMagnet(input,60,downloadDir);if(data==null)throw new Exception("No torrent metadata received. Check the link and available peers.");}else if(input.startsWith("https://"))data=network(input,8*1024*1024);else data=bytes(new FileInputStream(input),8*1024*1024);TorrentInfo ti=new TorrentInfo(data);String id=ti.infoHash().toHex();synchronized(this){for(int i=0;i<jobs.length();i++)if(jobs.getJSONObject(i).optString("id").equals(id))return jobs.getJSONObject(i);}Files.write(new File(downloadDir,id+".torrent").toPath(),data);JSONArray files=new JSONArray();for(int i=0;i<ti.numFiles();i++){String name=ti.files().filePath(i);if(supported(name)){safeFile(downloadDir,name);files.put(new JSONObject().put("name",name).put("size",ti.files().fileSize(i)));}}if(files.length()==0)throw new Exception("This torrent contains no EPUB, PDF, CBZ or CBR books");TorrentHandle h=startTorrent(ti);handles.put(id,h);JSONObject j=new JSONObject().put("id",id).put("input",input).put("files",files).put("progress",0).put("status","Choose file");synchronized(this){jobs.put(j);}return j;}
 private synchronized void tick(){try{boolean active=false;for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);TorrentHandle h=handles.get(j.optString("id"));if(h!=null&&h.isValid()&&j.optString("status").equals("Downloading")&&j.has("index")){int index=j.getInt("index");long size=h.torrentFile().files().fileSize(index);long[] progress=h.fileProgress();double fraction=size==0?1:Math.min(1,(double)progress[index]/size);TorrentStatus status=h.status();j.put("progress",fraction).put("speed",status.downloadRate()).put("peers",status.numPeers());if(fraction>=1){h.pause();j.put("status","Complete");}}if(j.optString("status").equals("Downloading"))active=true;}write("jobs",jobs);if(!active)getContext().stopService(new Intent(getContext(),DownloadService.class));}catch(Throwable e){android.util.Log.w("Folio","Progress",e);}}
 private JSONArray comic(File file) throws Exception{Map<String,byte[]> pages=new TreeMap<>((a,b)->natural(a,b));long[] total={0};if(file.getName().endsWith(".cbz")){try(ZipFile zip=new ZipFile(file)){Enumeration<? extends ZipEntry> en=zip.entries();while(en.hasMoreElements()){ZipEntry e=en.nextElement();if(e.isDirectory()||!image(e.getName()))continue;if(e.getName().contains(".."))throw new Exception("Unsafe comic archive");byte[] data=bytes(zip.getInputStream(e),32L*1024*1024);total[0]+=data.length;if(total[0]>128L*1024*1024)throw new Exception("Comic exceeds 128 MB decoded size");pages.put(e.getName(),data);}}}else{try(Archive rar=new Archive(file)){for(FileHeader h:rar.getFileHeaders()){if(h.isDirectory()||!image(h.getFileName()))continue;if(h.getFullUnpackSize()>32L*1024*1024)throw new Exception("Comic page too large");ByteArrayOutputStream out=new ByteArrayOutputStream();rar.extractFile(h,out);byte[] data=out.toByteArray();total[0]+=data.length;if(total[0]>128L*1024*1024)throw new Exception("Comic exceeds 128 MB decoded size");pages.put(h.getFileName(),data);}}}JSONArray out=new JSONArray();for(Map.Entry<String,byte[]> entry:pages.entrySet()){String n=entry.getKey().toLowerCase();String mime=n.endsWith(".png")?"png":n.endsWith(".webp")?"webp":n.endsWith(".gif")?"gif":"jpeg";out.put(new JSONObject().put("name",entry.getKey()).put("url","data:image/"+mime+";base64,"+Base64.encodeToString(entry.getValue(),Base64.NO_WRAP)));}if(out.length()==0)throw new Exception("No images found in comic");return out;}
 private boolean image(String n){return n.toLowerCase().matches(".*\\.(png|jpe?g|webp|gif)$");}
 private int natural(String a,String b){String[] x=a.split("(?<=\\D)(?=\\d)|(?<=\\d)(?=\\D)"),y=b.split("(?<=\\D)(?=\\d)|(?<=\\d)(?=\\D)");for(int i=0;i<Math.min(x.length,y.length);i++){int c=x[i].matches("\\d+")&&y[i].matches("\\d+")?new java.math.BigInteger(x[i]).compareTo(new java.math.BigInteger(y[i])):x[i].compareToIgnoreCase(y[i]);if(c!=0)return c;}return Integer.compare(x.length,y.length);}
 @Override protected void handleOnDestroy(){timer.shutdownNow();pool.shutdownNow();if(session!=null)new Thread(()->session.stop()).start();getContext().stopService(new Intent(getContext(),DownloadService.class));}
}
